type Run = {run_id: string; scenario_id: string; policy_id: string; decision_at: string; result_as_of: string; reference_policy_id: string; timing_model_id?: string; scenario_count?:number; scenario_seed?:number; common_shock_weight?:number};
type Trade = {trade_label?: string; security_label?: string; counterparty_label?: string;observed_settled: boolean;fx_conversions: {sell_currency:string;sell_amount:string;buy_currency:string;buy_amount:string;pricing?:{rate_base?:string;rate_usd?:string;observed_date:string}}[];trade_id: string; counterparty_id: string; cash_pool_id: string; currency: string; settlement_amount: string; remaining_obligation: string; observed_pool_cash: string; instruction_state: string; ssi_status: string; minutes_to_deadline: number; deadline_at: string; executed_at: string; prediction: {score: number; status: string; factors: string[]; recommended_action: string}};
type Page = {model_predictions?:Prediction[];available_currencies?: string[];items: Trade[]; next_cursor: string | null};
type Detail = {fx_receipts: {fx_leg_id: string; amount: string; currency: string; state: string; expected_credit_at: string}[]; trade: Trade; observed_events: {event_id: string; event_type: string; event_time: string}[]; outcome_as_of: string; outcome: {missed_contractual_deadline: boolean | null; recovered_late: boolean; failure_reasons: string[]}};
type Plan = {plan_id: string; status: string; policy_id: string; fallback_used: boolean; failure_reason: string | null; budget_used_base: string; expected_cost_base: string; base_currency: string; allocations: {bucket: {cash_pool_id: string; currency: string}; incremental_reserve: string; expected_shortfall: string; observed_pool_cash: string}[]};
type Metrics = {currency: string; failed_count: number; trade_count: number; failed_notional?: string; total_cost: string; bridge_cost: string; late_cost: string; route_cost: string; budget_limit: string; budget_used: string};
